sim_before, sim_after, natures, sim_final2 = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
NAT = ['순수', '광기', '활발', '우울', '냉정']
VN = {'erpien': '에르피엔(요정)', 'furry': '수인 부락(수인)', 'ghost': '유령 늪(유령)', 'monatium': '모나티엄(엘프)', 'spirit': '정령산(정령)', 'dragon': '용족 동굴(용족)'}
L = []
w = L.append

def look_of(r):
    f = r['spine'].split('/')[-1]
    if f.startswith('nururing'): return f'종족 스킨 고정({r["skin"]}) — 성격 모습 없음'
    lk = looks.get(f)
    if not lk: return '?'
    s = f'{len(lk["have"])}/5 · 서로 다른 모습 {lk["distinct"]}'
    noicon = [k for k in NAT if not lk['looks'][k]['icon']]
    if noicon: s += f' · 아이콘 없음 {"·".join(noicon)}'
    if lk['sameGroups']: s += ' · 같은 모습 ' + ' / '.join('·'.join(g) for g in lk['sameGroups'])
    return s

