for vid in ['erpien', 'furry', 'ghost', 'monatium', 'spirit', 'dragon']:
    d = json.load(open(f'{B}/world/villages/{vid}.json', encoding='utf-8'))
    v = d['villages'][0]
    nm = lambda x: t[x]['name'] if x in t else x
    used = set()
    w(f'### {VN[vid]}\n')
    for fi, fl in enumerate(v['floors']):
        w(f'**{fi + 1}층 {fl["name"]}** — 보스 몸 `{fl["boss"][0]}`')
        for ti, pool in enumerate(fl['pools']):
            w(f'- {"약중강"[ti]}: ' + ' / '.join(' + '.join(nm(x) for x in line) for line in pool))
            for line in pool: used.update(line)
        w('- 엘리트: ' + ' / '.join(' + '.join(nm(x) for x in line) for line in fl['elites']))
        for line in fl['elites']: used.update(line)
        w('')
    races = collections.defaultdict(set)
    for x in used:
        if x in t: races[t[x]['race']].add(t[x]['mon'])
    w('종족 몬스터: ' + ', '.join(sorted(m for r, ms in races.items() if r not in ('없음', '(사도)') for m in ms)) + ' · 종족 없음: ' + ', '.join(sorted(races['없음'])) + '\n')

