w('- 경과: 다른 종족까지 넓혔다가(닫힘 0) 사용자 정정(「종족 클론 수가 부족하면 그 성격을 빼는 게 나을 듯」)으로 마을 종족만으로 되돌렸다.\n')
w('### 마을 × 속성 보스 후보 수\n')
w('칸 = 열림/닫힘 · 1층 후보 수(* = 1~2성이 없어 3성) / 2층 3성 후보 수\n')
import re
rows = {}; cur = None
for line in open(natures, encoding='utf-8'):
    m = re.match(r'^(\w+)\(', line)
    if m: cur = m.group(1); rows[cur] = {}; continue
    m = re.match(r'^\s+(\S+) (열림|닫힘) · 1층 후보\((.+?)\) (\d+)\(.*?\) · 2층 후보\(3성\) (\d+)\(', line)
    if m and cur: rows[cur][m.group(1)] = m.groups()[1:]
w('| 마을 | ' + ' | '.join(NAT) + ' |')
w('|---|' + '---|' * len(NAT))
for vid, r in rows.items():
    w(f'| {VN.get(vid, vid)} | ' + ' | '.join((f"{'**닫힘**' if r[n][0]=='닫힘' else '열림'} · {r[n][2]}{'*' if '없어' in r[n][1] else ''} / {r[n][3]}" if n in r else '?') for n in NAT) + ' |')
w('')
w('```')
w(open(natures, encoding='utf-8').read().strip())
w('```\n')

